const files = [
  ".ai/task/repair-w32-20260925/SPEC.md",
  ".ai/task/repair-w32-20260925/SCOPE.json",
  ".ai/task/repair-w32-20260925/ADJUDICATION-R2.json"
];
for (const file of files) {
  const r = await tools.exec_command({
    cmd: `sed -n '1,220p' ${file}`,
    workdir: "/workspace/tome4-chinese-translation",
    yield_time_ms: 10000,
    max_output_tokens: 30000,
    sandbox_permissions: "require_escalated",
    justification: "允许我完整只读任务 SPEC、SCOPE 与本轮裁决吗？"
  });
  text(`FILE ${file}\n${r.output}`);
}

const cmds = [
  {
    name: "WORKSET_ALL_INDEX",
    cmd: "jq -c '.items[] | {entry_revision_identity,normalized_path,section,source_tag,target_preimage_sha256,source_batch_id,source_verification:{actual_public_source_match,literal_source_match,public_source_path,source_file_sha256,matching_literal_lines}}' .ai/task/repair-w32-20260925/WORKSET.json"
  },
  {
    name: "WORKSET_TWO_FULL",
    cmd: "jq '.items[] | select(.entry_revision_identity==\"2ceaa318deef24a29480d827263d5ad47c1b2e0dbe551f2865d322e82cfd1c8e\" or .entry_revision_identity==\"4555f7111c53b6c0e80083bb8955fa94c4437290485284925c30ebb6f27b53aa\")' .ai/task/repair-w32-20260925/WORKSET.json"
  },
  {
    name: "ANCHORS_STRUCTURE",
    cmd: "jq '{top_keys:keys, anchor_count:(.anchors // .items // .entries // [] | length)}' .ai/task/repair-w32-20260925/SOURCE-ANCHORS.json"
  }
];
for (const c of cmds) {
  const r = await tools.exec_command({
    cmd: c.cmd,
    workdir: "/workspace/tome4-chinese-translation",
    yield_time_ms: 10000,
    max_output_tokens: 30000,
    sandbox_permissions: "require_escalated",
    justification: "允许我只读核对 WORKSET 全部 26 条索引、两条目标完整冻结内容及 SOURCE-ANCHORS 结构吗？"
  });
  text(`${c.name}\n${r.output}`);
}

const cmds = [
  ["STATUS", "git status --short"],
  ["PHRASES", "rg -n -F -e '将军现在公务繁忙，至少目前是这样' -e '更不用说保持活跃的思维了' -e '将军现在正忙着，至少目前是这样' -e '更不用说还能一直行动了' tome-cults.lua"],
  ["VERIFY_SCRIPT", "sed -n '1,260p' .artifacts/i18n/repair-w32-20260925/verify_translation_diff.py"],
  ["I18N_USAGE", "rg -n -C 3 'lint --strict|luajit|LuaJIT' i18n/README.md"],
  ["PREV_REPORT", "sed -n '1,240p' .ai/task/repair-w32-20260925/execute-03-report.raw"]
];
for (const [name, cmd] of cmds) {
  const r = await tools.exec_command({
    cmd,
    workdir: "/workspace/tome4-chinese-translation",
    yield_time_ms: 10000,
    max_output_tokens: 30000,
    sandbox_permissions: "require_escalated",
    justification: "允许我只读核对工作树、目标短语和现有有界验证命令吗？"
  });
  text(`${name}\n${r.output}`);
}

const read = await tools.exec_command({
  cmd: "sed -n '1653p;2011p' tome-cults.lua",
  workdir: "/workspace/tome4-chinese-translation",
  yield_time_ms: 10000,
  max_output_tokens: 20000,
  sandbox_permissions: "require_escalated",
  justification: "允许我只读取得两条唯一目标所在的完整行，并用 apply_patch 做精确短语替换吗？"
});
const lines = read.output.replace(/\n$/, "").split("\n");
if (lines.length !== 2) throw new Error(`expected 2 lines, got ${lines.length}`);
const replacements = [
  ["更不用说保持活跃的思维了", "更不用说还能一直行动了"],
  ["将军现在公务繁忙，至少目前是这样", "将军现在正忙着，至少目前是这样"]
];
let patch = "*** Begin Patch\n*** Update File: /workspace/tome4-chinese-translation/tome-cults.lua\n";
for (let i = 0; i < 2; i++) {
  const [oldText, newText] = replacements[i];
  if (lines[i].split(oldText).length !== 2) throw new Error(`target ${i} not unique on expected line`);
  const updated = lines[i].replace(oldText, newText);
  patch += `@@\n-${lines[i]}\n+${updated}\n`;
}
patch += "*** End Patch";
const applied = await tools.apply_patch(patch);
text(applied);

const jobs = [
  ["TARGET_VERIFY", "python3 -B .artifacts/i18n/repair-w32-20260925/verify_translation_diff.py | jq '{verified,records,changed_count:(.changed|length),changed_revisions:[.changed[].revision],fixed_targets:[.changed[]|select(.revision==\"2ceaa318deef24a29480d827263d5ad47c1b2e0dbe551f2865d322e82cfd1c8e\" or .revision==\"4555f7111c53b6c0e80083bb8955fa94c4437290485284925c30ebb6f27b53aa\")|{revision,line,before,after}]}'"],
  ["STRICT_LINT", "python3 -B tools/i18n lint --strict"],
  ["DIFF_CHECK", "git diff --check"],
  ["BASELINE_SHA", "sha256sum .ai/task/repair-w32-20260925/baseline/tome-cults.lua"],
  ["HEAD_SHA", "git show HEAD:tome-cults.lua | sha256sum"]
];
const rs = await Promise.all(jobs.map(([name, cmd]) => tools.exec_command({
  cmd,
  workdir: "/workspace/tome4-chinese-translation",
  yield_time_ms: 30000,
  max_output_tokens: 30000,
  sandbox_permissions: "require_escalated",
  justification: "允许我运行用户要求的只读有界验证（LuaJIT 记录比较、strict lint、diff check）吗？"
})));
for (let i = 0; i < jobs.length; i++) {
  text(`${jobs[i][0]} exit=${rs[i].exit_code}\n${rs[i].output}`);
}

const cmds = [
  ["FINAL_STATUS", "git status --short"],
  ["NEW_PHRASES", "rg -n -F -e '将军现在正忙着，至少目前是这样' -e '更不用说还能一直行动了' tome-cults.lua"],
  ["OLD_PHRASE_1", "rg -c -F '将军现在公务繁忙，至少目前是这样' tome-cults.lua"],
  ["OLD_PHRASE_2", "rg -c -F '更不用说保持活跃的思维了' tome-cults.lua"],
  ["DIFF_STAT", "git diff --numstat -- tome-cults.lua"]
];
for (const [name, cmd] of cmds) {
  const r = await tools.exec_command({
    cmd,
    workdir: "/workspace/tome4-chinese-translation",
    yield_time_ms: 10000,
    max_output_tokens: 20000,
    sandbox_permissions: "require_escalated",
    justification: "允许我做最终只读核对，确认旧短语已消失且工作树范围未扩大吗？"
  });
  text(`${name} exit=${r.exit_code}\n${r.output}`);
}
